   Let's draft the analysis logic:
   ```java
   @Override
   public void afterCheckRootProject(@NonNull Context context) {
       for (Map.Entry<String, Set<String>> entry : layoutIncludes.entrySet()) {
           String rootLayout = entry.getKey();
           if (entry.getValue().isEmpty()) continue;

           // Map from id -> defining layout name
           Map<String, String> idToLayout = new HashMap<>();
           // Initialize with root layout's IDs
           Set<String> rootIds = layoutIds.getOrDefault(rootLayout, Collections.emptySet());
           for (String id : rootIds) {
               idToLayout.put(id, rootLayout);
           }

           // DFS/BFS to traverse includes
           Set<String> visited = new HashSet<>();
           Queue<String> queue = new ArrayDeque<>(entry.getValue());
           visited.add(rootLayout);

           while (!queue.isEmpty()) {
               String currentLayout = queue.poll();
               if (!visited.add(currentLayout)) continue;

               Set<String> currentIds = layoutIds.getOrDefault(currentLayout, Collections.emptySet());
               for (String id : currentIds) {
                   if (idToLayout.containsKey(id)) {
                       // Conflict found!
                       String originalLayout = idToLayout.get(id);
                       // Report on the include tag that brought in currentLayout
                       reportConflict(context, rootLayout, currentLayout, originalLayout, id);
                   } else {
                       idToLayout.put(id, currentLayout);
                   }
               }

               Set<String> nextIncludes = layoutIncludes.getOrDefault(currentLayout, Collections.emptySet());
               queue.addAll(nextIncludes);
           }
       }
       // Clear maps to free memory
       layoutIds.clear();
       layoutIncludes.clear();
       layoutIncludeElements.clear();
   }
   ```
