       String layoutName = context.getName().replace(".xml", "");
       layoutFiles.put(layoutName, context.file);
       layoutIds.computeIfAbsent(layoutName, k -> new HashSet<>());
       layoutIncludes.computeIfAbsent(layoutName, k -> new HashSet<>());
